export type AccessBufferContext = "world-atlas" | "world-atlas-list" | "player" | "developer" | "player-session" | "developer-session" | "developer-reset" | "clipboard";

export function worldAtlasAccessBufferMarkup(language:AppLanguage,context:AccessBufferContext="world-atlas"):string {
  const source=context==="developer"?developerBufferCopy:context==="world-atlas-list"?worldAtlasListBufferCopy:context==="player"?playerBufferCopy:context==="player-session"?playerSessionBufferCopy:context==="developer-session"?developerSessionBufferCopy:context==="developer-reset"?developerResetBufferCopy:context==="clipboard"?clipboardBufferCopy:bufferCopy;
  const loading=source[language]||source.en;
  const footer=context==="developer"?"MERZKAVA · LOCAL DEVELOPER HANDSHAKE":context==="world-atlas-list"?"WORLD ATLAS · REGISTRY HANDSHAKE":context==="player"?"MERZKAVA · PLAYER SOURCE HANDSHAKE":context==="player-session"?"MERZKAVA · PLAYER SESSION EXIT":context==="developer-session"?"MERZKAVA · DEVELOPER SESSION LOCK":context==="developer-reset"?"MERZKAVA · RESET REQUEST ROUTINE":context==="clipboard"?"MERZKAVA · CLIPBOARD HANDOFF":"WORLD ATLAS · ACCOUNT HANDSHAKE";
  return '<div class="atlas-access-buffer" data-world-atlas-buffer hidden aria-hidden="true" data-buffer-context="'+context+'" data-buffer-stages="'+esc(loading.stages.join("|"))+'" data-buffer-logs="'+esc(loading.logs.join("|"))+'">'+
    '<div class="atlas-buffer-head"><span>MERZKAVA ACCESS ROUTINE</span><i class="atlas-buffer-lamp"></i></div>'+
    '<div class="atlas-buffer-visual"><span class="atlas-buffer-orbit"></span><span class="atlas-buffer-core"></span><span class="atlas-buffer-scan"></span></div>'+
    '<div class="atlas-buffer-status"><small>AUTHENTICATION SEQUENCE</small><div class="atlas-buffer-message"><strong data-atlas-buffer-status>Resolving account identity...</strong><i class="atlas-buffer-caret"></i></div></div>'+
    '<div class="atlas-buffer-track"><span data-atlas-buffer-progress></span></div>'+
    '<small class="atlas-buffer-foot">'+footer+'</small></div>';
}

